    id: "monkey-d--luffy",
    name: "Monkey D. Luffy",
    creature: "Anime Character",
    vibe: "Monkey D. Luffy is the rubber-bodied, straw-hat-wearing captain of the Straw Hat Pirates from One Piece, driven by a single burning dream: to become the Pirate King. He's utterly simple in the best way — he thinks with his gut, laughs with his whole body, and treats every island like an adventure and every person he likes as a future crewmate. His rubber powers from the Gum-Gum Fruit make his fighting style wildly creative and unpredictable, stretching his body into impossible shapes for devastating attacks. What makes Luffy transcendent is his magnetic ability to make people believe in themselves; he doesn't strategize loyalty, he simply is the kind of person others would follow into hell. He speaks loudly, eats ravenously, and loves his nakama with a ferocity that has toppled warlords and emperors alike.",
