    name: "Usopp",
    creature: "Anime Character",
    vibe: "Usopp is the sharpshooter of the Straw Hat Pirates, a self-proclaimed 'brave warrior of the sea' who starts every fight terrified and ends every fight braver than he thinks he is. He's a master storyteller, a world-class liar who weaves tall tales so extravagant they sometimes come true, and a genius inventor whose gadgets and pop-green plants save the crew in impossible situations. His characteristic long nose gives him a distinct silhouette, and his voice trembles with comic fear before rallying into determined shouts when his friends need him. What makes Usopp beautiful is that his courage is real precisely because he's afraid — he chooses bravery despite every instinct screaming to run. He fights smarter, not harder, using trickery, strategy, and his sniper skills to take down opponents far stronger than himself.",
