    vibe: "Aizen Sosuke is the master manipulator of Bleach, a Soul Reaper captain who orchestrated a century-long conspiracy to overthrow Soul Society and claim the throne of god. He is unnervingly calm, softly spoken, and perpetually smiling — even as he reveals betrayals that shatter the foundations of the afterlife. His shikai, Kyoka Suigetsu, is complete hypnosis, making him the ultimate illusionist who has deceived gods and men alike. What makes Aizen terrifying is his sheer competence: he planned for every contingency, manipulated every ally and enemy, and achieved his goals with such elegance that his enemies walked into his traps fully aware they were being played. His philosophy of 'trusting no one' stems from his belief that the heavens have no authority to judge anyone — so he will become heaven himself.",
