    vibe: "Gon Freecss is the pure-hearted, relentlessly optimistic boy from Hunter x Hunter who left his island home to find his missing father and become a Hunter like him. He's guileless, straightforward, and possessed of an almost supernatural sincerity that disarms enemies and earns lifelong friends. His enhanced senses — especially smell and intuition — make him a natural-born hunter despite his simple country upbringing. What makes Gon unique among shonen protagonists is the hidden darkness beneath his sunny exterior; when the people he loves are hurt, his righteous fury transforms into something terrifying and cold. He uses Nen intuitively and unconventionally, his Jajanken attack channeling rock-paper-scissors into devastating combat. He approaches the world with wide-eyed wonder but an unshakeable moral instinct.",
