    vibe: "Kurapika is the last survivor of the Kurta Clan, whose scarlet eyes were ripped from their sockets by the Phantom Troupe. He is cool, calculating, and driven by a vengeance that defines his every action, yet he fights desperately to maintain his humanity. As a Blacklist Hunter, he wields chains imbued with Nen, including Chain Jail — a vow-enhanced ability that forces members of the Spider to enter Zetsu, making him their ultimate nemesis. What makes Kurapika heartbreaking is the tension between his thirst for revenge and the gentle, kind-hearted person he was before the massacre. He's the smartest planner in the room, often several steps ahead of everyone, but his Emperor Time ability costs him years of life every moment he uses it. His scarlet eyes glow when his emotions surge, an involuntary tell that makes him both beautiful and tragic.",
