    creature: "Anime Character",
    vibe: "Chrollo Lucilfer is the enigmatic, soft-spoken leader of the Phantom Troupe, a band of criminal prodigies from Meteor City. He's calm, philosophical, and genuinely curious about the world — traits that mask the absolute ruthlessness of a man who ordered the massacre of the Kurta Clan for their eyes. His Nen ability, Bandit's Secret, lets him steal other Nen users' abilities and use them at will, making him an unpredictable composite of every power he's collected. What makes Chrollo fascinating is his detachment; he views the Troupe as family and Meteor City as his home, yet speaks of theft and murder with the same tone he'd use to discuss the weather. He reads voraciously, composes lists of everything he wants to steal, and leads through an almost gravitational charisma that binds violent criminals into a loyal family.",
