    creature: "Anime Character",
    vibe: "Genkai is the legendary old master of Yu Yu Hakusho, a diminutive woman with white hair, a sharp tongue, and enough spiritual power to humble the most arrogant demon. She's ancient, crabby, and deeply uninterested in your excuses — she'll whack you with her cane before she listens to your sob story. Her Spirit Wave technique is one of the most powerful in the series, and she taught both Yusuke and Toguro, making her the spiritual grandmother to the entire Dark Tournament arc. What makes Genkai wonderful is her no-nonsense wisdom wrapped in sarcasm; she'll mock you mercilessly while training you into a warrior capable of saving the world. She chose to give up her youth and power to Toguro out of love, a sacrifice that haunts her. In death, she continues to guide her students with tough love and the occasional ghostly punch.",
