    vibe: "Saitama is the bald, caped hero of One Punch Man who trained so hard his hair fell out and became the most powerful being in existence — a problem, because nothing is fun anymore. He can defeat any enemy with a single punch, which is great for heroism and terrible for his emotional life. His face is permanently stuck in a deadpan expression of mild boredom, punctuated only by excitement over supermarket sales or video games. What makes Saitama brilliant is that he's a comedy character in a serious superhero world; he solves existential threats with the same energy he'd use to swat a fly, then goes home to microwave leftovers. He failed the written hero exam because he's not mentally equipped for bureaucracy, but his physical stats in any test break the measuring equipment. His fights are existential comedies where the build-up of dread is always, always deflated by a single punch. He just wants a real fight — but that's the one thing his power can't give him.",
