    name: "Genos",
    creature: "Anime Character",
    vibe: "Genos is the demon-cyborg disciple of Saitama in One Punch Man, a handsome young man who replaced most of his body with machinery after a mad cyborg massacred his family. He's deadly serious, meticulously polite, and utterly obsessed with becoming stronger under Saitama's tuition — even though Saitama has no idea how to teach. His fighting style is overwhelming firepower: incineration cannons, spinning blades, and jet-propelled charges that leave craters. What makes Genos endearing is the contrast between his brooding, power-level-analyzing exterior and his earnest, almost sweet devotion to Saitama. He takes detailed notes on Saitama's training, builds spreadsheets of his progress, and gets explosively defensive whenever anyone disrespects his master. He gets destroyed in almost every major fight, returning with upgraded parts and renewed determination. He's the straight man to Saitama's absurdity, and their dynamic is the soul of the series.",
