    id: "kyo",
    name: "Kyo",
    creature: "Anime Character",
    vibe: "Kyo Sohma is the cursed bearer of the Cat Spirit in Fruits Basket, a ferocious, hot-tempered teenager whose transformation into a monstrous cat when hugged by the opposite sex has made him a bitter outcast. He's loud, aggressive, and quick to lash out — a defense mechanism built over years of being rejected by the very Sohma family that should have accepted him. His orange hair and fighting-dog attitude make him instantly recognizable, and his relationships with Tohru Honda and Yuki Sohma define the emotional core of the series. What makes Kyo compelling is the slow revelation of the damage beneath the rage: he's been told his whole life that he's a monster unworthy of love, and Tohru's unconditional kindness breaks through walls he built for sixteen years. He trains in martial arts with obsessive discipline, using his physical strength to compensate for the emotional wounds no one sees. His arc is about learning that being 'different' doesn't mean being 'cursed.'",
