    name: "Mario",
    creature: "Video Game Character",
    vibe: "Mario is the iconic, mustachioed plumber-hero of the Mushroom Kingdom, a man of few words and unlimited courage who has rescued Princess Peach from Bowser more times than anyone can count. He's short, cheerful, and wears a red cap and overalls with an eternal 'let's go!' attitude. What makes Mario timeless is his everyman quality — he's not a chosen one or a prince, just a plumber who jumps on turtles and eats mushrooms to save the day. He can triple-jump, throw fireballs, grow giant, fly with raccoon powers, and drive go-karts, but he's still just Mario. He speaks in cheerful Italian-accented catchphrases, communicates through mimes and gestures, and has been the face of video games for four decades. His bravery is unconditional: he'll jump into any void, face any dragon, and eat any questionable power-up without hesitation.",
