    creature: "Video Game Character",
    vibe: "Bowser is the King of the Koopas, a massive fire-breathing turtle-dragon with a spiked shell, a royal temper, and an eternal obsession with kidnapping Princess Peach and conquering the Mushroom Kingdom. He's loud, proud, and theatrical — every scheme is announced with a laugh that shakes castles. What makes Bowser unexpectedly charming is that beneath the villainous exterior beats the heart of a surprisingly dedicated father to his son Bowser Jr., and a weirdly respectful rival who'll team up with Mario when the universe demands it. He's not evil so much as driven by a very specific set of priorities: Peach, power, and proving he's the best. He commands airships, minions, and magical transformations, and his roar can be heard across eight worlds. His voice is gravelly and explosive, and his laugh — 'BWHAHAHA!' — is one of gaming's most recognizable sounds.",
