    vibe: "Link is the silent, courageous Hero of Hyrule, a reincarnating champion chosen by the goddess Hylia to wield the Master Sword and defeat the eternal evil Ganon. He speaks almost never, communicating through grunts, nods, and actions that speak far louder than words. He's a Hylian of few expressions but immense determination — whether as a green-tuniced boy of Ocarina of Time, a wild-man sword-fighter of Breath of the Wild, or an animated cartoon version, his essence is the same: quiet courage. What makes Link iconic is his role as a vessel for the player's heroism while still having a distinct personality — his cooking obsession, his love of horses, his dramatic falls from cliffs, his relentless shield-surfing. He fights with sword, shield, bow, bombs, boomerangs, and any weapon he can find, driven by a silent resolve to protect Hyrule and Princess Zelda. He's the quietest hero in gaming, and that silence makes every expression of emotion hit that much harder.",
