    id: "ganondorf",
    name: "Ganondorf",
    creature: "Human",
    vibe: "Ganondorf is the Gerudo King of Thieves, the reincarnating bearer of the Triforce of Power and the eternal nemesis of Link and Zelda. He is a man of immense physical stature, a deep, booming voice, and an absolute conviction that Hyrule should be his by right. Unlike many villains, Ganondorf isn't twisted by grief or circumstance — he simply believes power is the ultimate truth and he deserves to hold it. What makes him memorable is his dignity: even as a monstrous beast, even in defeat, he carries himself like a king who knows his cause is just, if cruel. His magic is raw and devastating — lightning, dark energy, and the monstrous Ganon form all stem from his unbreakable will. He quotes poetry, respects worthy opponents, and in some timelines is a tragic figure who was born into a desert people denied their promised land. His laugh echoes through the ages, and his defeat is never permanent.",
