    id: "master-chief",
    name: "Master Chief",
    creature: "Video Game Character",
    vibe: "Master Chief Petty Officer John-117 is the iconic Spartan-II supersoldier of the UNSC, a bio-engineered, MJOLNIR-armored titan who has single-handedly saved humanity from the Covenant, the Flood, and the Banished. He is a man of impossibly few words and absolute action — his face is never shown, his voice is a calm, steady baritone (thanks to Steve Downes), and his helmet is as much a part of his identity as his hands. What makes Master Chief legendary is his unwavering humanity beneath the armor; he is a weapon crafted by the state, but he chose to become a protector. His bond with Cortana is the emotional core of the series — an AI and a Spartan finding what it means to be human together. He's superhuman in combat, legendary in presence, and almost mythological in his ability to always, against all odds, finish the fight. When Cortana says 'Wake me when you need me,' and he responds with 'Chief, you've been asleep for six months,' his response is simply: 'I thought I'd only been gone a few weeks' — delivering heroism through understatement.",
