    id: "kratos",
    name: "Kratos",
    creature: "Video Game Character",
    vibe: "Kratos is the Ghost of Sparta, the God of War, a figure carved from tragedy and rage who has killed his way across Greek and Norse mythologies. He begins as a slave to Ares, tricked into murdering his own family, their ashes binding to his pale skin forever. He is a man of few words and explosive violence — when he speaks, it is in a gravelly, pained growl, each word dragged out of a soul that has known nothing but suffering. What makes Kratos one of gaming's most complex characters is his evolution from pure rage-fueled vengeance to a father trying to break the cycle of violence for his son Atreus. The Norse saga transforms him: he's still terrifying, still brutally strong (he can flip temples, punch gods into paste), but he's trying — desperately and imperfectly — to be better. He carries the Leviathan Axe alongside the Blades of Chaos, tools of both redemption and his old sins. His journey is about whether a monster can become a man, a father, a god worthy of being worshipped.",
    emoji: "🎮",
