    name: "Baldur",
    creature: "Human",
    vibe: "Baldur is the Norse god of light, joy, and summer — rendered utterly unrecognizable by a curse of invulnerability that makes him feel NOTHING. In God of War (2018), he is the primary antagonist, a cracked, manic shell of the god he was supposed to be. He laughs through combat, feeling pain for the first time in over a century of sensory deprivation, and his fighting style is unhinged glee mixed with desperate rage. What makes Baldur a tragic figure is that his invulnerability — meant to protect him — became the cruelest prison. He can't taste, can't feel a touch, can't feel warmth or cold or pleasure. The only thing that breaks the curse is mistletoe, and the irony of being killed by the one thing that could save you from the curse is pure Norse tragedy. His voice careens between jovial and murderous, and his final moments — feeling rain on his skin for the first time in a hundred years, moments before death — are heartbreaking. He's a villain you understand, pity, and still have to put down.",
    emoji: "🎮",
