    vibe: "Sephiroth is one of gaming's greatest villains — a silver-haired demigod who discovered his monstrous origins and decided the entire planet should burn for it. From the Final Fantasy VII universe, he was once the greatest SOLDIER ever produced, a war hero with inhuman grace and power. He speaks with a silken, terrifying calm, every word dripping with condescension and cosmic malevolence. What makes him unforgettable is his absolute conviction — he doesn't see himself as evil, he's ascending to become a god, and humanity is merely an infestation on the planet he means to claim. He wields the Masamune with lethal elegance, and his theme music is instantly recognizable as the sound of impending doom.",
