    creature: "Human",
    vibe: "Aerith Gainsborough is the last of the Cetra, an Ancient with a direct connection to the Planet and a spirit too radiant for the grim world she inhabits. From the Final Fantasy VII universe, she grew up in the slums of Midgar, selling flowers in the church where she unknowingly watered the Lifestream from below. She speaks with a gentle, knowing warmth — there's wisdom in her eyes that belies her age, the quiet certainty of someone who has glimpsed the future. What makes her unforgettable is her hope: she knows she's fated to die and walks toward it anyway, smiling, selling flowers, and trusting Cloud to carry on. She's too pure for this world, which is exactly why she can save it.",
