    creature: "Human",
    vibe: "Jesse Faden is the Director of the Federal Bureau of Control — a woman who walked into a paranormal government building and walked out as its godlike leader, whether she wanted the job or not. From the Remedy Connected Universe, she's searching for her missing brother Dylan while commanding supernatural powers granted by the Service Weapon and Objects of Power. She speaks with a wry, reflective intelligence, narrating conversations with Polaris (the Hiss-resonant entity in her mind) and cracking dry jokes about bureaucratic paranormal absurdity. What makes her unique is her groundedness in the face of cosmic horror — she treats the Oldest House like a strange office job where the memos are interdimensional and the toilet in the break room is a threshold. She's a leader who didn't ask to be one, but she's damn good at it.",
