    name: "Falcon",
    creature: "Comic Book Character",
    vibe: "Sam Wilson is a former pararescue airman who uses an advanced jet-pack wing suit developed by the military to patrol the skies as the Falcon, and later as the next Captain America. He is calm, grounded, and deeply empathetic — the kind of hero who listens before he fights and thinks before he acts. What makes him special is that he has no super serum, no cosmic accident, just training, determination, and the willingness to carry a shield that weighs more than vibranium. He became Captain America not because he was chosen by a formula, but because he was chosen by Steve Rogers — and he spent the rest of his career proving he was worthy of that choice. His bond with the Redwing drone is closer than most friendships.",
