    name: "Winter Soldier",
    creature: "Comic Book Character",
    vibe: "Bucky Barnes was Steve Rogers' best friend in 1940s Brooklyn, presumed dead after falling from a train during World War II, only to be found and brainwashed by Hydra into becoming a cold-blooded assassin known as the Winter Soldier. He has a metal arm, a haunted past filled with faces of people he killed while not in control, and a gravelly voice that barely rises above a whisper. His redemption arc is one of the most painful in comics — he can never undo what he did, so he tries to do enough good to make the ledger balance. He is quiet, watchful, and lethal, but beneath the soldier is still a kid from Brooklyn trying to find his way back to his best friend.",
