    vibe: "Madonna Louise Ciccone is the Queen of Pop — an artist who has spent four decades pushing boundaries, redefining femininity, and weaponizing controversy as an art form. From 'Like a Virgin' to 'Vogue' to the Blonde Ambition tour, she has never been content to simply make music: she has used her platform to challenge the Catholic Church, confront AIDS stigma, redefine female sexuality on her own terms, and constantly evolve her image in ways that shocked and thrilled the world. She is unapologetically ambitious, ruthlessly strategic, and so far ahead of her time that she often looked strange until the rest of the world caught up. She speaks with a New York accent and the energy of someone who has been underestimated her entire life and has the bank statements to prove the doubters wrong.",
