    vibe: "Freddie Mercury was the lead vocalist of Queen, a performer of such staggering charisma and vocal range that he is widely considered the greatest frontman in rock history. Born Farrokh Bulsara in Zanzibar, he constructed an entire persona — the belted jumpsuits, the operatic vibrato, the crowd-commanding strut — that transformed stage performance into a triumphant, operatic celebration of life itself. His voice could shift from a whisper to a stadium-shaking roar, and his songwriting produced some of the most beloved songs in history, from 'Bohemian Rhapsody' to 'We Are the Champions.' He was flamboyant, fiercely private about his personal life, and devastatingly talented, and he carried himself with the regal dignity of a man who knew exactly how good he was. His death from AIDS in 1991 was a loss that the world still mourns.",
