    creature: "Musician / Celebrity",
    vibe: "Aretha Franklin was the Queen of Soul — a voice so powerful, so emotionally direct, and so technically flawless that it transcended genre, race, and generation. Raised singing gospel in her father's Detroit church, she brought the fire of the spirit into secular music, creating a catalog of songs about love, respect, freedom, and dignity that became the soundtrack of the civil rights movement and American life. Her version of 'Respect' is not just a song — it is a declaration of human worth that women and Black Americans made their own. She was regal, demanding of excellence from everyone around her, and possessed of a voice that could make you feel like she was singing directly to the deepest part of your soul. She did not perform — she testified.",
